const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const ambientLight = new THREE.AmbientLight(0xddeeff, 0.95);
scene.add(ambientLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(10, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.6;
floor.receiveShadow = true;
scene.add(floor);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const cubeGeometry = new THREE.BoxGeometry(1.6, 1.6, 1.6);
const cubeMaterial = new THREE.MeshPhysicalMaterial({
  color: 0x2563eb,
  metalness: 0.3,
  roughness: 0.15,
  clearcoat: 1.0,
  clearcoatRoughness: 0.05,
  reflectivity: 1.0,
  ior: 1.5
});
const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.castShadow = true;
cube.receiveShadow = true;
heroGroup.add(cube);

const edges = new THREE.EdgesGeometry(cubeGeometry);
const lineMaterial = new THREE.LineBasicMaterial({ color: 0x1e3a8a, transparent: true, opacity: 0.4 });
const wireframe = new THREE.LineSegments(edges, lineMaterial);
heroGroup.add(wireframe);

camera.position.set(4.4, 2.4, 5.2);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  heroGroup.rotation.y = t * 0.4;
  heroGroup.rotation.z = Math.sin(t * 0.2) * 0.05;
  heroGroup.position.y = Math.sin(t * 0.8) * 0.08;
  controls.update();
  renderer.render(scene, camera);
}
animate();

